contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: deposit some ether and then attempt withdrawAll from caller
    // Inputs:
    //  - sender: address that will call withdrawAll (msg.sender simulated by the caller of this function)
    //  - amount: amount of wei to send to c before withdraw
    //  - recipient: address to receive funds from c

    // Note: This function must be called in tests with appropriate msg.sender and with
    // contract having enough balance to send to c (use payable on this test caller externally).
    function check(address sender, uint256 amount, address payable recipient) public {
        // Precondition: this test contract must have at least `amount` wei to fund c
        require(address(this).balance >= amount);

        // fund c so it has balance to transfer
        payable(address(c)).transfer(amount);

        // Ensure we observe who is owner via public getter
        address owner = c.owner();

        // The key behavior: withdrawAll should only succeed when called by owner.
        // Call withdrawAll as the caller of this function (so msg.sender for c.withdrawAll is this contract).
        // To model different callers, tests should deploy or call this check from different addresses.
        // We record the recipient balance before and after the call to observe success.
        uint256 before = address(recipient).balance;

        // perform the state-changing call on c
        c.withdrawAll(recipient);

        uint256 after = address(recipient).balance;

        // Assert: withdrawAll transfers the full previous balance of c to recipient iff this caller equals owner.
        // We express the rule as: (after - before == amount) == (owner == address(this))
        // That is, recipient receives the funds exactly when the caller is the owner.
        assert(((after - before) == amount) == (owner == address(this)));
    }

    // Allow this test contract to receive ether so it can fund c
    receive() external payable {}
    fallback() external payable {}
}

