        require(owner == c.owner(), "owner must match c.owner()");

        // Fund target contract c by sending Ether to it
        // Note: using funder parameter only for clarity; the actual transfer comes from this contract
        payable(address(c)).transfer(amount);

        // Ensure c has balance before withdrawal
        require(address(c).balance == amount, "c must be funded");

        // Call withdrawAll as owner: the caller of this function is this contract.
        // To act as owner, the owner must be this contract in the real test harness.
        // We still enforce that caller equals owner by requiring owner == address(this)
        require(owner == address(this), "this contract must be owner to call withdrawAll");

        // Perform the withdrawal specifying recipient
        c.withdrawAll(recipient);

        // Observables: c balance must be zero after withdrawal, and this contract's balance
        // should only increase if this contract was the intended recipient.
        // The distinguishing property: if recipient != address(this), this contract's balance must not increase from the withdrawal.

        // Capture balances
        uint256 cBal = address(c).balance;
        uint256 selfBal = address(this).balance;

        // Assert the general rule: c's balance is zero, and if this contract was not the specified recipient, it does not receive the withdrawn funds.
        assert(cBal == 0 && (recipient == address(this) || selfBal <= amount));
    }
